tinymce.create("tinymce.plugins.Footnotes",{init:(t,o)=>{t.addButton("footnotes",{title:"footnotes",cmd:"footnotes",image:o+"/../images/fn-wysiwyg.png"}),t.addCommand("footnotes",(function(){jQuery.ajax({type:"POST",url:"./admin-ajax.php",data:{action:"footnotes_getTags",nonce:footnotesEditor.nonce},success:o=>{const e=JSON.parse(o),n=e.start+t.selection.getContent()+e.end;t.insertContent(n)},error:(t,o,e)=>{console.error("Error: "+e)}})}))},getInfo:()=>({longname:"footnotes",author:"Mark Cheret",authorurl:"https://cheret.tech/footnotes/",infourl:"https://wordpress.org/plugins/footnotes/",version:"2.7.4d"})}),tinymce.PluginManager.add("footnotes",tinymce.plugins.Footnotes);
